public static boolean isBalanced(int[] arr, int index) {
    int left = 0;
    int right = 0;
    for (int i = 0; i < index; i++) {
        left = left + arr[i];
    }
    for (int i = index + 1; i < arr.length; i++) {
        right = right + arr[i];
    }
    return left == right;
}

public static boolean isBalancedArray(int[] arr) {
    for (int i = 0; i < arr.length; i++) {
        if (isBalanced(arr, i)) {
            return true;
        }
    }
    return false;
}

